"""
    Change a certain value from a dictionary.

    Parameters
    ----------
    dictionary : dict
        Input dictionary.
    old_value : str, NoneType, bool
        The value to be changed.
    new_value : str, NoneType, bool
        Replace value.

    Returns
    -------
    dict
    """
def change_dict_value(dictionary: Any, old_value: Any, new_value: Any) -> object {
    for (key, value) in dictionary.items() {
        if (value == old_value) {
            dictionary[key] = new_value;
        }
    }
    return dictionary;
}

"""Return 10^n: 10^n > num; 10^(n-1) <= num."""
def nifty_power_of_ten(num: Any) -> object {
    result = 10;
    while (result <= num) {
        result *= 10;
    }
    return result;
}

